-- uk_5.lua: Ukrainian for en_5.lua (Forever Dungeon Journal long texts).
return {
  ["e2d4cdbd"] = "Знайдіть три самоцвіти командування: «{item:Gemstone of Smolderthorn}», «{item:Gemstone of Spirestone}» і «{item:Gemstone of Bloodaxe}». Принесіть їх разом із предметом «{item:Unadorned Seal of Ascension}» до НІП «{npc:Vaelan}». Генерали: «{npc:War Master Voone}» із клану Тліючого Шипа, «{npc:Highlord Omokk}» із клану Шпилекаменя і «{npc:Overlord Wyrmthalak}» із клану Кривавої Сокири.",
  ["958e536b"] = "Знайдіть предмет «{item:Bijou's Belongings}» і поверніть його власниці. Хай щастить!",
  ["4dcabca9"] = "НІП «{npc:Bijou}» ховається в ніші за першими мостами. Її речі з’являються в одному з кількох місць біля залів тролів та орків.",
  ["413b1614"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і з’ясуйте, що сталося з НІП «{npc:Bijou}».",
  ["49f71b16"] = "Знайдіть предмет «{item:Bijou's Belongings}» і поверніть його власниці. Ви пригадуєте, як вона казала, що сховала речі на нижньому поверсі міста.",
  ["995d92b5"] = "Потім віднесіть предмет «{item:Bijou's Reconnaissance Report}» до НІП «{npc:Lexlort}» у місцевості «{zone:Kargath}», щоб отримати нагороду.",
  ["dad9783e"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте босів «{npc:War Master Voone}», «{npc:Highlord Omokk}» та «{npc:Overlord Wyrmthalak}». Коли впораєтеся, поверніться до НІП «{npc:Marshal Maxwell}».",
  ["edd240ee"] = "Убийте босів «{npc:Highlord Omokk}», «{npc:War Master Voone}» та «{npc:Overlord Wyrmthalak}». Здобудьте предмет «{item:Important Blackrock Documents}». Виконавши завдання, поверніться до НІП «{npc:Warlord Goretooth}» у місцевості «{zone:Kargath}».",
  ["26ce1cf3"] = "Поговоріть із воєначальником Ґортутом, щоб отримати від нього предмет-наказ, і клацніть по ньому, щоб почати завдання. Предмет «{item:Important Blackrock Documents}» з’являється біля трьох генералів.",
  ["6fc97641"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте джерело загрози від воргів. Коли ви йшли від Гелендіса, він вигукнув ім’я: «{npc:Halycon}». Так орки називають ворга, про якого йдеться.",
  ["427c70f3"] = "Убийте ворга «{npc:Halycon}», матір воргового лігва. Будьте готові до появи боса «{npc:Gizrul the Slavener}», який прийде по вас одразу після неї.",
  ["9dd67542"] = "Убийте ворга «{npc:Halycon}», ватажку зграї воргів клану Кривавої Сокири.",
  ["53220682"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знайдіть цуценят воргів Кривавої Сокири. Переносьте цих лютих звірят у клітці. Принесіть предмет «{item:Caged Worg Pup}» до НІП «{npc:Kibler}».",
  ["67740207"] = "Застосуйте видану клітку до істоти «{npc:Bloodaxe Worg Pup}» у лігві воргів.",
  ["6d252ccc"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і зберіть яйця «{item:Spire Spider Egg}»: 15 шт. для НІП «{npc:Kibler}». Судячи з усього, ці яйця можна знайти біля павуків.",
  ["1e35ffc3"] = "Павучі яйця лежать у павучих тунелях.",
  ["90ec4468"] = "У серці підземелля «{zone:Blackrock Spire}» ви знайдете боса «{npc:Mother Smolderweb}». Вступіть із нею в бій і дайте їй вас отруїти. Поверніться до НІП «{npc:Ragged John}», поки отрута діє, щоб він міг вас «подоїти».",
  ["20fb36d4"] = "Отримайте отруту від боса «{npc:Mother Smolderweb}» і дійдіть до НІП «{npc:Ragged John}», поки вона діє. Не дозволяйте нікому її зняти.",
  ["94eb5d66"] = "Прочитайте предмет «{item:Warosh's Scroll}». Принесіть предмет «{item:Warosh's Mojo}» до НІП «{npc:Warosh}».",
  ["ca18742e"] = "Принесіть голову боса й предмет «{item:Roughshod Pike}» до купи підношень за павуками, щоб почалися хвилі ворогів.",
  ["ed1c082a"] = "Віднесіть предмет «{item:General Drakkisath's Command}» до НІП «{npc:Marshal Maxwell}» у локації «{zone:Burning Steppes}».",
  ["3294b886"] = "Веде до завдання «{quest:General Drakkisath's Demise}» у Верхньому Шпилі Блекрок.",
  ["35991dd8"] = "Принесіть п’яту й шосту таблички Мош’ару до НІП «{npc:Prospector Ironboot}» у локації «{zone:Tanaris}».",
  ["8c1605c9"] = "П’ята й шоста таблички Мош’ару лежать на ділянці тролів Тліючого Шипа. Далі йдуть завдання «{quest:Confront Yeh'kinya}» і «{quest:The Hand of Rastakhan}».",
  ["25f3773a"] = "Вирушайте до локації «{zone:Burning Steppes}» і передайте предмет «{item:Bijou's Information}» НІП «{npc:Marshal Maxwell}».",
  ["06c9546a"] = "Принесіть третю й четверту таблички Мош’ару до НІП «{npc:Prospector Ironboot}» у локації «{zone:Tanaris}».",
  ["0ef6a95f"] = "Поговоріть із НІП «{npc:Warlord Goretooth}», щоб вступити до лав «{npc:Kargath Expeditionary Force}».",
  ["ce72ca7f"] = "Нове в цій версії гри: це завдання йде перед завданням «{quest:Warlord's Command}».",
  ["cff4b6fb"] = "Вирушайте до місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}». Знайдіть стародавнього дрейка «{npc:Emberstrife}» і бийте його, доки не зламаєте його волю. Покладіть перед ним предмет «{item:Unforged Seal of Ascension}», потім застосуйте до нього предмет «{item:Orb of Draconic Energy}» і змусьте його спрямувати своє полум’я на предмет «{item:Unforged Seal of Ascension}».",
  ["48327f09"] = "Віднесіть невикувану печатку й предмет «{item:Orb of Draconic Energy}» до дрейка «{npc:Emberstrife}» у місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}». Викувана печатка відчиняє двері Верхнього Шпиля Блекрок.",
  ["5095ea12"] = "Знайдіть тавро, яке охороняє бос «{npc:General Drakkisath}», і отримайте з нього знак, щоб користуватися сферою командування.",
  ["3ca5cee8"] = "НІП «{npc:Scarshield Quartermaster}» стоїть у коридорі біля порталу до місцевості «{zone:The Spire}». Торкніться «{zone:Drakkisath's Brand}» за босом «{npc:General Drakkisath}»: це відкриває швидкий шлях через ланцюжок завдань до рейду «{zone:Blackwing Lair}».",
  ["d3617ed7"] = "Принесіть яйця «{item:Collected Dragon Egg}»: 8 шт. і предмет «{item:Collectronic Module}» до НІП «{npc:Tinkee Steamboil}» у місцевості «{zone:Flame Crest}» у локації «{zone:Burning Steppes}».",
  ["304e6214"] = "Якщо застосувати модуль до яєць у місцевості «{zone:The Rookery}», з них можуть вилупитися дракончики.",
  ["4e87a377"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і знищте боса «{npc:General Drakkisath}». Коли впораєтеся, поверніться до НІП «{npc:Marshal Maxwell}».",
  ["31db1c01"] = "Убийте боса «{npc:General Drakkisath}» наприкінці Верхнього Шпиля Блекрок.",
  ["b5201f38"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і вбийте боса «{npc:Warchief Rend Blackhand}». Заберіть його голову й поверніться до міста «{zone:Orgrimmar}».",
  ["64f8ec2e"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і зберіть очі «{item:Black Dragonspawn Eye}»: 20 шт. Виконавши завдання, поверніться до НІП «{npc:Myranda the Hag}».",
  ["cd0a9cf3"] = "Частина ланцюжка Орди до Оніксії. Ці очі випадають із драконідів у Верхньому Шпилі Блекрок.",
  ["58d7b2d3"] = "Вам треба здобути предмет «{item:Blood of the Black Dragon Champion}» у боса «{npc:General Drakkisath}». Він перебуває у своїй тронній залі в глибині підземелля «{zone:Blackrock Spire}».",
  ["4cb3f3bd"] = "Частина допуску до боса «{npc:Onyxia}».",
  ["1b380a0d"] = "Вирушайте до підземелля «{zone:Blackrock Spire}» і вбийте боса «{npc:General Drakkisath}». Наберіть його крові й віднесіть її до НІП «{npc:Rexxar}».",
  ["bf754726"] = "Вирушайте до підземелля «{zone:Blackrock Spire}», убийте боса «{npc:Goraluk Anvilcrack}» і застосуйте до його трупа предмет «{item:Blood Stained Pike}». Також знайдіть предмет «{item:Unforged Rune Covered Breastplate}». Віднесіть предмет «{item:Soul Stained Pike}» і нагрудник до НІП «{npc:Lorax}» у локації «{zone:Winterspring}».",
  ["b226ce3e"] = "Ковальство 270 (бронник). Застосуйте предмет «{item:Blood Stained Pike}» до трупа Ґоралука і підберіть поруч предмет «{item:Unforged Rune Covered Breastplate}».",
  ["4863bc64"] = "Поговоріть із НІП «{npc:Mayara Brightwing}» у локації «{zone:Burning Steppes}».",
  ["52648c18"] = "Вступний крок до завдання «{quest:Doomrigger's Clasp}».",
  ["caf8e4e5"] = "Принесіть предмет «{item:Doomrigger's Clasp}» до НІП «{npc:Mayara Brightwing}» у локації «{zone:Burning Steppes}».",
  ["77155b02"] = "Ця скриня стоїть у місцевості «{zone:The Rookery}». Потім здайте завдання «{quest:Delivery to Ridgewell}» НІП «{npc:Count Remington Ridgewell}» у місцевості «{zone:Stormwind Keep}», щоб отримати нагороду.\n\nНеобов’язкове вступне завдання:",
  ["b6e50d32"] = "Поговоріть із НІП «{npc:Shadowmage Vivian Lagrave}».",
  ["a75f1984"] = "Вступний крок до завдання «{quest:The Darkstone Tablet}».",
  ["6970add4"] = "Предмет «{item:Darkstone Tablet}» лежить на землі в місцевості «{zone:The Rookery}».\n\nНеобов’язкове вступне завдання:",
  ["cf7d7aac"] = "Поговоріть із НІП «{npc:Malyfous Darkhammer}» у місцевості «{zone:Everlook}».",
  ["1a53ae91"] = "Він з’являється з трупа боса «{npc:The Beast}» після бою. Потім Маліфус пропонує обміни на предмет «{item:Pristine Hide of the Beast}».",
  ["cb8b2d44"] = "Вирушайте до локації «{zone:Winterspring}» і знайдіть НІП «{npc:Haleh}». Віддайте їй луску дракона «{npc:Awbee}».",
  ["a1b2cab2"] = "НІП «{npc:Awbee}» — поранений синій дракон біля шляху до арени після Ренда. Скористайтеся руною глибоко в печері «{zone:Mazthoril}», щоб дістатися до НІП «{npc:Haleh}».",
  ["af02bf05"] = "Принесіть предмет «{item:Broodling Essence}»: 8 шт. і Драко-Інкарцинатрикс 900 до НІП «{npc:Tinkee Steamboil}» у місцевості «{zone:Flame Crest}» у локації «{zone:Burning Steppes}».",
  ["9c43b12c"] = "Застосуйте предмет «{item:Eggscilloscope Prototype}» до яйця в місцевості «{zone:The Rookery}».",
  ["2db2cb9a"] = "Передайте предмет «{item:Tinkee's Letter}» НІП «{npc:Felnok Steelspring}».",
  ["3a9d6d87"] = "Принесіть роги «{item:Uncracked Chillwind Horn}»: 8 шт. до НІП «{npc:Felnok Steelspring}».",
  ["acd91e7e"] = "Принесіть предмет «{item:Felnok's Package}» до НІП «{npc:Tinkee Steamboil}» у локації «{zone:Burning Steppes}».",
  ["3839de23"] = "Поговоріть із НІП «{npc:Tinkee Steamboil}».",
  ["794a143b"] = "Поговоріть із НІП «{npc:Eitrigg}» у місті «{zone:Orgrimmar}». Обговоривши справи з НІП «{npc:Eitrigg}», попросіть поради в НІП «{npc:Thrall}». Ви пригадуєте, що бачили НІП «{npc:Eitrigg}» у покоях НІП «{npc:Thrall}».",
  ["623b193d"] = "Вирушайте до міста «{zone:Stormwind City}» і дійдіть до міської брами. Поговоріть із НІП «{npc:Squire Rowe}», щоб він повідомив НІП «{npc:Marshal Windsor}» про ваше прибуття.",
  ["b57ccd76"] = "Ідіть за НІП «{npc:Reginald Windsor}» через місто «{zone:Stormwind}». Захистіть його від небезпеки!",
  ["3ad1391f"] = "Вам треба знайти у світі істоту, здатну відновити силу предмета «{item:Fragment of the Dragon's Eye}». Усе, що ви знаєте про таку істоту, — що вона існує.",
  ["6482b68c"] = "Вислухайте НІП «{npc:Thrall}».",
  ["dc6f686e"] = "Розшукайте НІП «{npc:Rexxar}». Вождь розповів вам, де його шукати. Обшукайте шляхи локації «{zone:Desolace}» між локаціями «{zone:Stonetalon Mountains}» і «{zone:Feralas}».",
  ["9b6cae57"] = "Доставте предмет «{item:Rexxar's Testament}» до НІП «{npc:Myranda the Hag}» у локації «{zone:Western Plaguelands}».",
  ["716cdbc6"] = "Вирушайте до місцевості «{zone:Wyrmbog}» у локації «{zone:Dustwallow Marsh}» і знайдіть лігво «{zone:Emberstrife's Den}». Усередині надягніть предмет «{item:Amulet of Draconic Subversion}» і поговоріть із дрейком «{npc:Emberstrife}».",
  ["091b65be"] = "Вам треба знайти дрейка-чемпіона синього драконячого роду «{npc:Scryer}» і вбити його. Вийміть череп із його трупа й віднесіть до дрейка «{npc:Emberstrife}». Ви знаєте, що він мешкає в локації «{zone:Winterspring}».",
  ["8bf10d57"] = "Знищте дрейка-чемпіона зеленого роду, Сомнуса. Заберіть його череп і віднесіть до дрейка «{npc:Emberstrife}».",
  ["85bdaa81"] = "Місцевість «{zone:Caverns of Time}» у пустелі Танаріс охороняє дрейк «{npc:Chronalis}», нащадок Ноздорму. Знищте його й віднесіть його череп до дрейка «{npc:Emberstrife}».",
  ["b2a161b0"] = "Вирушайте до місцевості «{zone:Grim Batol}» і вистежте дрейка «{npc:Axtroz}», чемпіона червоного роду. Знищте його й заберіть його череп. Віднесіть череп до дрейка «{npc:Emberstrife}».",
  ["2b78ba16"] = "Схоже, виставу закінчено. Ви знаєте, що предмет «{item:Amulet of Draconic Subversion}», який зробила для вас НІП «{npc:Myranda the Hag}», не діятиме в підземеллі «{zone:Blackrock Spire}». Можливо, варто знайти НІП «{npc:Rexxar}» і пояснити, у якій ви скруті. Покажіть йому предмет «{item:Dull Drakefire Amulet}». Сподіваймося, він знатиме, що робити далі.",
  ["8dac25e4"] = "Вирушайте до підземелля «{zone:Dire Maul}» і знайдіть біса «{npc:Pusillin}». Будь-якими засобами переконайте біса «{npc:Pusillin}» віддати вам його книгу. Якщо здобудете предмет «{item:Book of Incantations}», поверніться до НІП «{npc:Azj'Tordin}» у місцевості «{zone:Lariss Pavilion}» у локації «{zone:Feralas}».",
  ["70724029"] = "Наздоганяйте біса «{npc:Pusillin}» крилом і говоріть із ним, доки він не почне бій, тоді вбийте його заради книги. З нього також випадає предмет «{item:Crescent Key}».",
  ["25704102"] = "Поговоріть із НІП «{npc:Latronicus Moonspear}» у місцевості «{zone:Feathermoon Stronghold}» у локації «{zone:Feralas}».",
  ["a19833ba"] = "Вступний крок до завдання «{quest:Lethtendris's Web}».",
  ["a397bbb2"] = "Принесіть павутину до НІП «{npc:Latronicus Moonspear}» у місцевості «{zone:Feathermoon Stronghold}» у локації «{zone:Feralas}».",
  ["39ec3bf0"] = "Павутина випадає з боса «{npc:Lethtendris}».\n\nНеобов’язкове вступне завдання:",
  ["cb1eaf6c"] = "Поговоріть із НІП «{npc:Talo Thornhoof}» у місцевості «{zone:Camp Mojache}» у локації «{zone:Feralas}».",
  ["6a6ba1cf"] = "Принесіть предмет «{item:Lethtendris's Web}» до НІП «{npc:Talo Thornhoof}» у місцевості «{zone:Camp Mojache}» у локації «{zone:Feralas}».",
  ["7e48f3e9"] = "Знайдіть Лозу Скверни в підземеллі «{zone:Dire Maul}» і здобудьте з неї уламок. Найімовірніше, отримати його вдасться лише після загибелі боса «{npc:Alzzin the Wildshaper}». Надійно запечатайте уламок у предметі «{item:Reliquary of Purity}» і віднесіть до НІП «{npc:Rabine Saturna}» у місцевості «{zone:Nighthaven}» (локація «{zone:Moonglade}»).",
  ["5ac4b825"] = "Убийте боса «{npc:Alzzin the Wildshaper}», підберіть біля лози предмет «{item:Felvine Shard}» і запечатайте його в предметі «{item:Reliquary of Purity}».",
  ["94fabbc4"] = "Вирушайте до підземелля «{zone:Dire Maul}» і вбийте водяного елементаля «{npc:Hydrospawn}». Поверніться з предметом «{item:Hydrospawn Essence}» до НІП «{npc:Lorekeeper Lydros}» у залі «{zone:Athenaeum}».",
  ["7c2f50ac"] = "Класове завдання мага. Лідрос перебуває в залі «{zone:Athenaeum}» (північне/західне крило); предмет «{item:Hydrospawn Essence}» випадає з боса «{npc:Hydrospawn}» у східному крилі. Нагорода: заклинання мага, ранг 7.",
  ["fe7a8ff0"] = "Вирушайте до локації «{zone:Silithus}» і пошукайте предмет «{item:Reliquary of Purity}» серед руїн місцевості «{zone:Southwind Village}». Якщо знайдете його, повертайтеся з ним до НІП «{npc:Rabine Saturna}» у місцевості «{zone:Nighthaven}» (локація «{zone:Moonglade}»).",
  ["22e7e9a0"] = "Знищте вартових біля 5 пілонів, які живлять місцевість «{zone:Prison}» демона «{npc:Immol'thar}». Коли пілони вимкнуться, силове поле навколо демона «{npc:Immol'thar}» зникне. Увійдіть до місцевості «{zone:Prison}» демона «{npc:Immol'thar}» і знищте мерзенного демона в її серці. Нарешті, зійдіться в бою з босом «{npc:Prince Tortheldrin}» у залі «{zone:Athenaeum}». Виконавши завдання, поверніться до НІП «{npc:Shen'dralar Ancient}» у дворі.",
  ["800fdc5b"] = "Убийте вартових усіх п’яти пілонів, потім боса «{npc:Immol'thar}», потім боса «{npc:Prince Tortheldrin}». Поверніться до Прадавнього Шен’дралара, візьміть «{zone:Treasure of the Shen'dralar}» і відкрийте скриню під сходами бібліотеки, щоб отримати нагороду.",
  ["ba7be09d"] = "Пошукайте в підземеллі «{zone:Dire Maul}» зниклого НІП. Повідомте все, що дізнаєтеся, НІП «{npc:Sage Korolusk}» у місцевості «{zone:Camp Mojache}».",
  ["32516866"] = "Взаємодійте зі скелетними рештками поруч із НІП «{npc:Lorekeeper Lydros}» у залі «{zone:Athenaeum}». Відкриває обміни лібрамів у Лідроса.",
  ["3dbc2fb4"] = "Пошукайте в підземеллі «{zone:Dire Maul}» зниклого НІП. Повідомте все, що дізнаєтеся, НІП «{npc:Scholar Runethorn}» у фортеці Фезермун.",
  ["de09c045"] = "Знайдіть Селище Зорепаду в локації «{zone:Winterspring}» і поговоріть із НІП «{npc:Wynd Nightchaser}».",
  ["46f252d1"] = "Вступний крок до завдання «{quest:Fragments of the Past}».",
  ["701919f4"] = "Принесіть предмет «{item:Enchanted Thorium Bar}», предмет «{item:Crystal Restore}»: 5 шт. і предмет «{item:Vial of Dire Water}» до НІП «{npc:Aurora Skycaller}» біля місцевості «{zone:Northpass Tower}» у локації «{zone:Eastern Plaguelands}».",
  ["63bc30f5"] = "Наповніть її флакон у зловісному ставку в місцевості «{zone:Eldreth Row}» у західному крилі підземелля «{zone:Dire Maul}»; також принесіть 1 предмет «{item:Enchanted Thorium Bar}» і «{item:Crystal Restore}»: 5 шт.\n\nНеобов’язкове вступне завдання:",
  ["56c2ba1f"] = "Здобудьте особливий корм для духа коня. Схоже, такий корм можна дістати в НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}». Вирушайте до підземелля «{zone:Dire Maul}» у локації «{zone:Feralas}» і вбийте боса «{npc:Tendris Warpwood}». Так ви звільните духа «{npc:Ancient Equine Spirit}». Нагодуйте його особливим кормом, щоб заспокоїти. Насамкінець віддайте йому предмет «{item:Arcanite Barding}», щоб він його благословив.",
  ["a2615301"] = "Завдання паладина на бойового коня. Убийте боса «{npc:Tendris Warpwood}», потім нагодуйте духа «{npc:Ancient Equine Spirit}» і віддайте йому предмет «{item:Arcanite Barding}». Візьміть із собою предмет «{item:Manna-Enriched Horse Feed}» від НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}».",
  ["e1eed8e7"] = "Знайдіть предмет «{item:Gauntlet of Gordok Might}» і поверніть його до НІП «{npc:Captain Kromcrush}» у підземеллі «{zone:Dire Maul}». За словами Кромкраша, «давня байка» каже, що Тортельдрін — «моторошний» ельф, який називав себе принцом, — украв її в одного з королів Ґордоків.",
  ["2547afd3"] = "Мета в західному крилі: предмет «{item:Gauntlet of Gordok Might}» лежить у скрині біля боса «{npc:Prince Tortheldrin}». Саме завдання видає дружній НІП «{npc:Captain Kromcrush}» у північному крилі підземелля «{zone:Dire Maul}», коли ви станете королем Ґордоків.",
  ["1ab93ba2"] = "Прочитайте інструкції «{item:Mor'zul's Instructions}». Призвіть істоту «{npc:Xorothian Dreadsteed}», здолайте її, а потім прив’яжіть її дух до себе.",
  ["61847503"] = "Завдання чорнокнижника на коня жаху. Коли бос «{npc:Immol'thar}» загине, проведіть ритуал у його в’язниці з предметами «{item:J'eevee's Jar}», «{item:Black Lodestone}» і «{item:Xorothian Glyphs}». Візьміть із собою уламки душі.",
  ["2864bb7d"] = "Поговоріть із НІП «{npc:Jaron Stoneshaper}» у місцевості «{zone:Starfall Village}».",
  ["2d5485a6"] = "Скористайтеся предметом «{item:Jaron's Pick}», щоб знайти чотири уламки реліквій. Принесіть їх до НІП «{npc:Aurora Skycaller}» у локації «{zone:Eastern Plaguelands}».",
  ["5106be4b"] = "Знайдіть предмет «{item:Sacred Highborne Writings}» у місцевості «{zone:Temple of Zin-Malor}» у локації «{zone:Azshara}» і принесіть його до НІП «{npc:Aurora Skycaller}» біля місцевості «{zone:Northpass Tower}» у локації «{zone:Eastern Plaguelands}».",
  ["92de6d08"] = "Принесіть 30 пляшок предмета «{item:Raging Beast's Blood}» до НІП «{npc:Mor'zul Bloodbringer}» у локації «{zone:Burning Steppes}».",
  ["8dc2fe41"] = "Принесіть предмет «{item:Case of Blood}» до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["8a27329d"] = "Купіть зілля у НІП «Ґорзікі» в локації «{zone:Burning Steppes}». Скористайтеся зіллями, щоб пройти через місцевість «{zone:Jaedenar}», і поговоріть із НІП «{npc:Lord Banehollow}».",
  ["813a705b"] = "Зійдіться з НІП «{npc:Ulathek}», потім принесіть предмет «{item:The Traitor's Heart}» до НІП «{npc:Lord Banehollow}» у місцевості «{zone:Jaedenar}».",
  ["3225dab0"] = "Купіть предмет «{item:Xorothian Stardust}» у НІП «{npc:Ur'dan}». Принесіть його до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["bbbe64e8"] = "Принесіть еліксири «{item:Elixir of Shadow Power}»: 10 шт. до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["089736ba"] = "Принесіть уламки «{item:Large Brilliant Shard}»: 6 шт. і руду «{item:Dark Iron Ore}»: 25 шт. до НІП «Ґорзікі» в локації «{zone:Burning Steppes}».",
  ["14fad7da"] = "Принесіть луски «{item:Black Dragonscale}»: 35 шт. до НІП «{npc:Gorzeeki Wildeyes}» у локації «{zone:Burning Steppes}».",
  ["87c5b19b"] = "Принесіть злитки «{item:Arcanite Bar}»: 3 шт. до НІП «Ґорзікі» в локації «{zone:Burning Steppes}».",
  ["12e4c01d"] = "Вирушайте до міста «{zone:Ironforge}» і дістаньте предмет «Кадило Екзорцизму» в НІП «Верховний Жрець Роган». Щоб отримати її, доведеться пожертвувати 150 золотих.",
  ["ae1712f9"] = "Поверніть предмет «{item:Exorcism Censer}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["427a1a25"] = "Застосуйте предмет «{item:Exorcism Censer}», щоб вигнати духів, які мучать місцевість «{zone:Terrordale}». Коли вб’єте духів «{npc:Terrordale Spirit}»: 25, поверніться до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}».",
  ["fef59fbe"] = "Поговоріть із НІП «{npc:Grimand Elmore}» у кварталі «{zone:Dwarven District}» міста «{zone:Stormwind}».",
  ["91c108db"] = "Принесіть тканину «Рунна Тканина»: 40 шт., злитки «{item:Arcanite Bar}»: 6 шт., предмет «{item:Arthas' Tears}»: 10 шт., флакони «{item:Stratholme Holy Water}»: 5 шт. і 150 золотих до НІП «{npc:Grimand Elmore}» у кварталі «{zone:Dwarven District}» міста «{zone:Stormwind}».",
  ["254e1701"] = "Здобудьте галети «{item:Enriched Manna Biscuit}»: 20 шт. — головний складник предмета «{item:Manna-Enriched Horse Feed}» — для НІП «{npc:Merideth Carlson}» у місцевості «{zone:Southshore}» у локації «{zone:Hillsbrad Foothills}». Відомо, що єдиний постачальник цих галет — «{npc:The Argent Dawn}». Також треба дати їй 50 золотих, щоб заспокоїти її вражені почуття.",
  ["59999a7d"] = "Віднесіть предмет «{item:Arcanite Barding}» до НІП «{npc:Lord Grayson Shadowbreaker}» у місті «{zone:Stormwind}», щоб він його оглянув.",
}
